<script setup>
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import ActionIcon from './components/ActionIcon.vue';
import {useActionName} from './action-name';
import ActionIconPicker from './components/ActionIconPicker.vue';
import IconSelect from './components/IconSelect.vue';
import PluginActionFields from './components/PluginActionFields.vue';
import TriggerRecorder from './components/TriggerRecorder.vue';
import WheelEditor from './components/WheelEditor.vue';
import GesturePad from './components/GesturePad.vue';
import GestureGlyph from './components/GestureGlyph.vue';
const model=window.skkModel;
const confirmation=ref(null),confirmDialog=ref(null),actionDialog=ref(null),actionDraft=ref(null),draftError=ref('');let confirmResolve=null,actionContext=null;
function askConfirm(message){confirmation.value=message;return new Promise(resolve=>confirmResolve=resolve)}
function answerConfirm(value){confirmation.value=null;confirmResolve?.(value);confirmResolve=null}
watch(confirmation,async value=>{await nextTick();if(value)confirmDialog.value?.showModal();else confirmDialog.value?.close()});
watch(actionDraft,async value=>{await nextTick();if(value)actionDialog.value?.showModal();else actionDialog.value?.close()});
function beginAction(copy=null,bind=false){actionDraft.value=copy?{...JSON.parse(JSON.stringify(copy)),id:id(),name:copy.name+' 副本'}:{id:id(),name:'',type:'key',value:'',args:[]};actionContext=bind?{wheelId:wheel.value.id,...selection.value}:null;draftError.value=''}
function cancelAction(){actionDraft.value=null;actionContext=null;cancelKeyRecording()}
function saveNewAction(){const a=JSON.parse(JSON.stringify(actionDraft.value));a.name=a.name.trim();const probe=JSON.parse(JSON.stringify(c.value));probe.actions.push(a);const errors=model.validate(probe);if(errors.length){draftError.value=errors.join('；');return}c.value.actions.push(a);ai.value=c.value.actions.length-1;if(actionContext){const w=c.value.wheels.find(w=>w.id===actionContext.wheelId);if(w){if(actionContext.ring==='outside'&&w.outsideMode==='single')w.outsideActionId=a.id;else w[actionContext.ring==='second'?'secondSlots':actionContext.ring==='outside'?'outsideSlots':'slots'][actionContext.index]=a.id}}cancelAction();changed()}

const actionSearch=ref(''), savedConfig=ref(''), wheelTab=ref('editor'), gestureTab=ref('editor');
function selectedWheelIndex(){return Math.max(0,c.value.wheels.findIndex(w=>w.enabled))}
function selectWheel(){c.value.wheels.forEach((w,i)=>w.enabled=i===wi.value);c.value.wheelEnabled=true;changed()}

const descriptions={overview:'你的常用操作，都在鼠标旁。',wheel:'选择扇区，直接安排每一个动作。',gesture:'画下你的习惯，让轨迹变成操作。',actions:'集中管理动作，在轮盘与手势中重复使用。',general:'管理应用排除、配置备份与后台运行。'};
const actionTypes={key:'快捷键',app:'应用',path:'文件',url:'网址',text:'文本',plugin:'插件指令'};
const filteredActions=computed(()=>c.value?.actions.map((a,i)=>({a,i})).filter(({a})=>a.name.toLowerCase().includes(actionSearch.value.toLowerCase()))||[]);

function markSaved(){savedConfig.value=JSON.stringify(c.value);dirty.value=false}
async function discard(){if(await askConfirm('放弃所有未保存的设置修改？')){c.value=JSON.parse(savedConfig.value);wi.value=selectedWheelIndex();ai.value=0;resetPad();note.value='已恢复为保存的配置'}}

const pages=[['overview','总览','◉'],['wheel','快捷轮盘','◌'],['gesture','鼠标手势','⌁'],['actions','动作库','⌘'],['general','通用设置','⚙']];const page=ref('overview'),c=ref(null),runtime=ref({paused:true,status:'正在连接'}),note=ref(''),wi=ref(0),ai=ref(0),recording=ref(false),points=ref([]),pattern=ref(''),newName=ref(''),newAction=ref(''),recKey=ref(false),dirty=ref(false);let api,unsubscribe,toastTimer;const selection=ref({ring:'inner',index:0}),keyTarget=ref(null),templateStrokes=ref([]),padRevision=ref(0);
watch(c,()=>{if(c.value)dirty.value=JSON.stringify(c.value)!==savedConfig.value},{deep:true,flush:'sync'});
watch(note,value=>{clearTimeout(toastTimer);if(value)toastTimer=setTimeout(()=>note.value='',3000)});
watch(()=>runtime.value.lastError,value=>{if(value)note.value=value});
const drawnValid=computed(()=>templateStrokes.value.length===1&&model.validShape(templateStrokes.value));
const drawnMatch=computed(()=>drawnValid.value&&c.value?model.matchShape(templateStrokes.value,c.value.gestures.map(g=>({...g,enabled:true})),c.value.gesture.shapeThreshold):null);
const selectedSlots=computed(()=>wheel.value?.[selection.value.ring==='second'?'secondSlots':selection.value.ring==='outside'?'outsideSlots':'slots']);
const slotBinding=computed({get:()=>selection.value.ring==='outside'&&wheel.value?.outsideMode==='single'?wheel.value.outsideActionId:selectedSlots.value?.[selection.value.index],set:value=>{if(selection.value.ring==='outside'&&wheel.value.outsideMode==='single')wheel.value.outsideActionId=value;else selectedSlots.value[selection.value.index]=value;changed()}});
const actionOptions=computed(()=>c.value?[{value:'',label:'选择动作'},...c.value.actions.map(a=>({value:a.id,label:a.name,image:a.image,icon:a.icon||({key:'Keyboard',app:'App',path:'File',url:'Globe',text:'Text',plugin:'Plugin'}[a.type])}))]:[]);
const slotAction=computed(()=>c.value?.actions.find(a=>a.id===slotBinding.value));
watch(wi,()=>selection.value={ring:'inner',index:0});watch(page,async()=>{wheelTab.value='editor';gestureTab.value='editor';recKey.value=false;keyTarget.value=null;note.value='';await nextTick();document.querySelector('main')?.scrollTo(0,0)});
const wheel=computed(()=>c.value?.wheels[wi.value]),action=computed(()=>c.value?.actions[ai.value]);useActionName(actionDraft);useActionName(action);const labels={middle:'鼠标中键',right:'鼠标右键',x1:'侧键 X1',x2:'侧键 X2'};const directions={U:'↑',D:'↓',L:'←',R:'→'};const title=computed(()=>pages.find(x=>x[0]===page.value)?.[1]);
function cancelKeyRecording(){recKey.value=false;keyTarget.value=null}
watch([selection,ai,slotAction],cancelKeyRecording,{flush:'sync'});
watch(wheel,()=>{selection.value={ring:'inner',index:0};cancelKeyRecording()},{flush:'sync'});
const arrows=p=>[...(p||'')].map(x=>directions[x]).join(' ');const trigger=x=>[...x.modifiers,labels[x.button]].join(' + ');const id=()=>crypto.randomUUID();const nameFor=x=>c.value.actions.find(a=>a.id===x)?.name||'未设置';
async function run(fn){try{note.value='';await fn()}catch(e){note.value=e.message}}
async function save(){await run(async()=>{if(page.value==='wheel'&&wheel.value)selectWheel();await api.save(JSON.parse(JSON.stringify(c.value)));markSaved();note.value='设置已保存'})}
async function activate(){await run(async()=>{await api.save(JSON.parse(JSON.stringify(c.value)));markSaved();await api.activate()})}
function changed(){dirty.value=JSON.stringify(c.value)!==savedConfig.value}function copyAction(){beginAction(action.value)}function setCount(ring='inner'){const second=ring==='second',outside=ring==='outside',n=second?wheel.value.secondCount:outside?wheel.value.outsideCount:wheel.value.count,key=second?'secondSlots':outside?'outsideSlots':'slots';wheel.value[key]=Array.from({length:n},(_,i)=>wheel.value[key]?.[i]||'');selection.value={ring:second?'second':outside?'outside':'inner',index:0};changed()}
function resizeWheel(){if(wheel.value.size>=200&&wheel.value.size<=600)wheel.value.center=Math.min(wheel.value.center,Math.floor(wheel.value.size/3)-1);changed()}
function secondChanged(){if(!wheel.value.secondEnabled)selection.value={ring:'inner',index:0};changed()}
function createSlotAction(){beginAction(null,true)}
function resetPad(){templateStrokes.value=[];pattern.value='';padRevision.value++}
function onDrawingStart(){templateStrokes.value=[]}
function onRecorded(strokes){templateStrokes.value=strokes;if(!drawnValid.value)note.value='轨迹太短，请一笔画出完整手势'}
function addWheel(){c.value.wheels.push({...JSON.parse(JSON.stringify(c.value.wheels[0]||{button:'middle',modifiers:[],mode:'hold',count:8,size:280,center:36,delay:0,opacity:95,color:'#208b91',labels:true,slots:Array(8).fill(''),layoutVersion:3,secondEnabled:false,secondCount:8,secondSlots:Array(8).fill(''),outsideEnabled:false,outsideMode:'single',outsideActionId:'',outsideCount:8,outsideSlots:Array(8).fill(''),outsideTrigger:'release'})),id:id(),name:'新轮盘',enabled:false});wi.value=c.value.wheels.length-1;selectWheel()}
async function removeWheel(){if(await askConfirm('删除这个轮盘方案？')){c.value.wheels.splice(wi.value,1);wi.value=0;selectWheel()}}
function addAction(){beginAction()}
async function removeGesture(g){if(!await askConfirm('删除手势“'+g.name+'”？保存设置后生效。'))return;const index=c.value.gestures.findIndex(item=>item.id===g.id);if(index>=0){c.value.gestures.splice(index,1);changed()}}
async function removeAction(){const a=action.value;const refs=c.value.wheels.some(w=>[...w.slots,...(w.secondSlots||[]),...(w.outsideSlots||[]),w.outsideActionId].includes(a.id))||c.value.gestures.some(g=>g.actionId===a.id);if(!await askConfirm(refs?'此动作正在使用。删除后对应扇区将清空，相关手势将删除，是否继续？':'删除此动作？'))return;c.value.wheels.forEach(w=>{w.slots=w.slots.map(x=>x===a.id?'':x);w.secondSlots=w.secondSlots.map(x=>x===a.id?'':x);w.outsideSlots=w.outsideSlots.map(x=>x===a.id?'':x);if(w.outsideActionId===a.id)w.outsideActionId=''});c.value.gestures=c.value.gestures.filter(g=>g.actionId!==a.id);c.value.actions.splice(ai.value,1);ai.value=0;changed()}
function recordKey(e){if(!recKey.value)return;e.preventDefault();e.stopPropagation();if(e.key==='Escape'){recKey.value=false;return}if(['Control','Alt','Shift','Meta'].includes(e.key))return;const map={ArrowLeft:'Left',ArrowRight:'Right',ArrowUp:'Up',ArrowDown:'Down',' ':'Space',Esc:'Escape'};(keyTarget.value||action.value).value=[e.ctrlKey?'Ctrl':'',e.altKey?'Alt':'',e.shiftKey?'Shift':'',e.metaKey?'Win':'',map[e.key]||(/^[a-z]$/i.test(e.key)?e.key.toUpperCase():e.key)].filter(Boolean).join('+');recKey.value=false;keyTarget.value=null;changed()}
function gestureDraft(){if(!newAction.value)return {error:'请选择执行动作'};if(!drawnValid.value)return {error:'请先一笔绘制完整手势'};if(drawnMatch.value)return {error:'轨迹重复，对应动作：'+nameFor(drawnMatch.value.actionId)};return {kind:'shape',strokes:JSON.parse(JSON.stringify(templateStrokes.value))}}
function addGesture(){const draft=gestureDraft();if(draft.error){note.value=draft.error;return}c.value.gestures.push({id:id(),name:newName.value.trim()||'新手势',...draft,actionId:newAction.value,enabled:true});changed();resetPad();note.value='手势已加入草稿，保存后生效';newName.value='';}
function rerecord(g){if(!drawnValid.value){note.value='请先一笔绘制完整手势';return}const duplicate=model.matchShape(templateStrokes.value,c.value.gestures.filter(x=>x.id!==g.id).map(x=>({...x,enabled:true})),c.value.gesture.shapeThreshold);if(duplicate){note.value='轨迹重复，对应动作：'+nameFor(duplicate.actionId);return}g.kind='shape';g.strokes=JSON.parse(JSON.stringify(templateStrokes.value));delete g.pattern;changed();note.value='手势轨迹已替换，保存后生效'}
async function choose(a,kind){await run(async()=>{const p=await api.choose(kind);if(p){a.value=p;changed()}})}
async function importConfig(){await run(async()=>{const next=await api.import();if(next&&await askConfirm(`将使用导入的 ${next.wheels.length} 个轮盘、${next.gestures.length} 条手势替换当前配置。保存时会备份原配置，是否继续？`)){c.value=model.upgrade(next);wi.value=selectedWheelIndex();ai.value=0;changed()}})}
function beforeClose(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{api=window.skk;if(!api){const defaults=await fetch('./defaults.json').then(r=>r.json());api={snapshot:async()=>({config:defaults,paused:true,status:'浏览器预览 · 全局操作不可用'}),save:async()=>{throw Error('请在 ZTools 中保存设置')},activate:async()=>{throw Error('请在 ZTools 中启用鼠快快')},recognize:model.recognize,defaults:()=>model.upgrade(model.defaults()),choose:async()=>null,import:async()=>null,export:async()=>{throw Error('请在 ZTools 中导出')},pause:async()=>{}}}await run(async()=>{const snap=await api.snapshot();c.value=model.upgrade(snap.config);wi.value=selectedWheelIndex();markSaved();runtime.value=snap;unsubscribe=api.subscribe?.(s=>runtime.value=s)});window.addEventListener('keydown',recordKey,true);window.addEventListener('beforeunload',beforeClose)});
onUnmounted(()=>{clearTimeout(toastTimer);unsubscribe?.();window.removeEventListener('keydown',recordKey,true);window.removeEventListener('beforeunload',beforeClose)});
</script>
<template>
 <div class="shell" v-if="c" >
  <aside><div class="brand"><img class="brand-icon" :src="'./logo-coral.png'" alt="鼠快快鼠标图标"><div><strong>鼠快快</strong><small>一划一点，快捷随手。</small></div></div><nav aria-label="设置导航"><button v-for="p in pages" :key="p[0]" :class="{active:page===p[0]}" :aria-current="page===p[0]?'page':undefined" :title="p[1]" @click="page=p[0]"><span>{{p[2]}}</span>{{p[1]}}</button></nav><div class="aside-foot"><div class="listen-status"><span :class="['dot',{live:!runtime.paused}]"/><span class="listen-label">{{runtime.paused?'已暂停':'监听中'}}</span><button class="listen-toggle" role="switch" :aria-checked="!runtime.paused" :aria-label="runtime.paused?'恢复监听':'暂停监听'" @click="run(()=>api.pause(!runtime.paused))" :title="runtime.paused?'点击恢复监听':'点击暂停监听'"><span class="listen-switch" :class="{on:!runtime.paused}"/></button></div><small>鼠标轮盘与手势工具<br>v0.7.5 · Windows</small></div></aside>
  <main :data-page="page"><header v-if="page!=='overview'"><div><h1>{{title}}</h1></div></header>  <template v-if="page==='overview'"><section class="overview-status"><img class="status-emblem" :src="'./logo-coral.png'" alt="鼠标"><div><span class="eyebrow">一划一点，快捷随手。</span><h2>{{runtime.paused?'随时准备，再次出发':'鼠快快正在运行'}}</h2><p>{{runtime.paused?'恢复监听后，就能使用已保存的轮盘和手势。':'使用已保存的快捷配置，编辑设置时也不中断。'}}</p></div></section><div class="cards"><section><div class="section-title"><h3>快捷轮盘 <small>{{c.wheels.length}} 个方案</small></h3><input type="checkbox" v-model="c.wheelEnabled" aria-label="启用快捷轮盘"></div><p>{{c.wheels.length}} 个方案，{{c.wheels.filter(w=>w.enabled).map(trigger).join(' / ')||'暂无启用方案'}}</p><button @click="page='wheel'">编辑轮盘 →</button></section><section><div class="section-title"><h3>鼠标手势 <small>{{c.gestures.length}} 条轨迹</small></h3><input type="checkbox" v-model="c.gestureEnabled" aria-label="启用鼠标手势"></div><p>{{trigger(c.gesture)}} · {{c.gestures.filter(g=>g.enabled).length}} 条启用规则</p><button @click="page='gesture'">编辑手势 →</button></section></div><section class="quick-start"><h3>从一个常用操作开始</h3><div class="quick-links"><button @click="page='actions';addAction()"><strong>新建动作 →</strong><span>快捷键、应用、网址或文本</span></button><button @click="page='wheel'"><strong>安排轮盘 →</strong><span>点击扇区，选择要执行的动作</span></button><button @click="page='gesture'"><strong>录制手势 →</strong><span>自由画一条轨迹，再绑定动作</span></button></div></section></template>
  <template v-if="page==='wheel'"><div class="wheel-scheme toolbar"><select aria-label="当前轮盘方案" v-model="wi" @change="selectWheel"><option v-for="(w,i) in c.wheels" :value="i">{{w.name}}</option></select><button @click="addWheel">＋ 新建方案</button><button v-if="wheel" class="danger" @click="removeWheel">删除方案</button></div><div class="wheel-tabs" role="tablist" aria-label="轮盘设置"><button role="tab" :aria-selected="wheelTab==='editor'" :class="{active:wheelTab==='editor'}" @click="wheelTab='editor'">轮盘与动作</button><button role="tab" :aria-selected="wheelTab==='settings'" :class="{active:wheelTab==='settings'}" @click="wheelTab='settings'">触发与布局</button></div><template v-if="wheel"><section v-show="wheelTab==='editor'" class="wheel-stage"><div class="wheel-workspace"><WheelEditor :style="{'--accent':wheel.color}" :wheel="wheel" :actions="c.actions" :selection="selection" @select="v=>selection=v"/><div class="wheel-controls"><div class="slot-editor" aria-label="所选扇区动作设置"><h3>{{selection.ring==='inner'?'第一圈':selection.ring==='second'?'第二圈':'外圈'}} · 第 {{selection.index+1}} 项</h3><label>绑定动作<IconSelect label="轮盘绑定动作" v-model="slotBinding" :options="actionOptions" placeholder="选择动作" @change="changed"/></label><button class="primary" @click="createSlotAction">＋ 新建动作</button></div><div class="ring-switches"><button type="button" role="switch" :aria-checked="wheel.secondEnabled" aria-label="启用第二圈" @click="wheel.secondEnabled=!wheel.secondEnabled;secondChanged()"><span>第二圈</span><span class="listen-switch" :class="{on:wheel.secondEnabled}"/></button><button type="button" role="switch" :aria-checked="wheel.outsideEnabled" aria-label="启用外圈" @click="wheel.outsideEnabled=!wheel.outsideEnabled;selection={ring:'inner',index:0}"><span>外圈</span><span class="listen-switch" :class="{on:wheel.outsideEnabled}"/></button></div></div></div></section><div v-show="wheelTab==='settings'" class="wheel-settings-scroll"><div class="wheel-settings-cards">
<section class="wheel-setting-card wheel-setting-card--trigger" aria-labelledby="wheel-trigger-heading"><h3 id="wheel-trigger-heading">触发</h3><div class="form-grid"><label>方案名称<input v-model="wheel.name"></label><label>鼠标按键<select v-model="wheel.button"><option v-for="(v,k) in labels" :value="k">{{v}}</option></select></label><label>操作方式<select v-model="wheel.mode"><option value="hold">按住选择，松开执行</option><option value="click">点击打开，点击执行</option></select></label><label>触发延迟（毫秒）<input type="number" min="0" max="1000" v-model.number="wheel.delay"></label></div><div class="wheel-trigger-tools"><div class="modifiers"><span>同时按住</span><label v-for="m in ['Ctrl','Alt','Shift']"><input type="checkbox" :value="m" v-model="wheel.modifiers">{{m}}</label></div><TriggerRecorder :value="wheel" @recorded="v=>{wheel.button=v.button;wheel.modifiers=v.modifiers;changed()}"/></div></section>
<section class="wheel-setting-card wheel-setting-card--first" aria-labelledby="wheel-first-heading"><h3 id="wheel-first-heading">第一圈设置</h3><div class="wheel-first-fields"><label>扇区数量<select aria-label="第一圈扇区数量" v-model.number="wheel.count" @change="setCount()"><option v-for="n in [4,6,8,12]" :value="n">{{n}} 个</option></select></label><div class="wheel-size-control"><div><strong>轮盘大小</strong><span>{{wheel.size}} px · 跟随系统缩放</span></div><div class="wheel-size-inputs"><input aria-label="轮盘大小" type="range" min="200" max="600" step="10" v-model.number="wheel.size" @input="resizeWheel"><input aria-label="轮盘直径" type="number" min="200" max="600" step="10" v-model.number="wheel.size" @input="resizeWheel"></div></div></div></section>
<section class="wheel-setting-card wheel-setting-card--second" aria-labelledby="wheel-second-heading"><div class="section-title"><h3 id="wheel-second-heading">第二圈设置</h3><small>{{wheel.secondEnabled?'已启用':'未启用'}}</small></div><label>扇区数量<select aria-label="第二圈扇区数量" v-model.number="wheel.secondCount" :disabled="!wheel.secondEnabled" @change="setCount('second')"><option v-for="n in [4,6,8,12]" :value="n">{{n}} 个</option></select></label><p v-if="!wheel.secondEnabled" class="hint">在“轮盘与动作”中打开第二圈开关后可调整。</p></section>
<section class="wheel-setting-card wheel-setting-card--third" aria-labelledby="wheel-third-heading"><div class="section-title"><h3 id="wheel-third-heading">第三圈设置（外圈）</h3><small>{{wheel.outsideEnabled?'已启用':'未启用'}}</small></div><fieldset class="ring-settings-fields" :disabled="!wheel.outsideEnabled"><div class="form-grid"><label>外圈分区<select aria-label="第三圈分区" v-model="wheel.outsideMode" @change="selection={ring:'outside',index:0}"><option value="single">整个外圈执行同一动作</option><option value="direction">按方向配置不同动作</option></select></label><label>执行时机<select aria-label="第三圈执行时机" v-model="wheel.outsideTrigger"><option value="release">越界选中，松开或点击执行</option><option value="enter">越界立即执行一次</option></select></label><label v-if="wheel.outsideMode==='direction'">方向数量<select aria-label="第三圈方向数量" v-model.number="wheel.outsideCount" @change="setCount('outside')"><option v-for="n in [4,6,8,12]" :value="n">{{n}} 个方向</option></select></label></div></fieldset><p v-if="!wheel.outsideEnabled" class="hint">在“轮盘与动作”中打开外圈开关后可调整。</p><p v-if="wheel.outsideEnabled&&wheel.outsideTrigger==='enter'&&wheel.modifiers.length" class="hint">组合键触发时：应用与网址可立即打开；快捷键与文本会等你松开修饰键再执行，避免按键串入。</p></section>
<section class="settings-detail wheel-appearance-card"><div class="settings-card-heading"><h3>外观与防误触</h3></div><div class="detail-body"><div class="form-grid"><label>中心取消半径（DIP）<input type="number" min="20" :max="Math.floor(wheel.size/3)-1" v-model.number="wheel.center"></label><label>不透明度（30—100）<input type="number" min="30" max="100" v-model.number="wheel.opacity"></label><label>强调色<input type="color" v-model="wheel.color"></label><label><input type="checkbox" v-model="wheel.labels">显示动作名称</label></div></div></section>
</div></div></template><section v-else><p>还没有轮盘方案，点击“新建方案”开始配置。</p></section></template>
  <template v-if="page==='gesture'"><div class="gesture-tabs wheel-tabs" role="tablist" aria-label="手势设置"><button role="tab" :aria-selected="gestureTab==='editor'" :class="{active:gestureTab==='editor'}" @click="gestureTab='editor'">手势与动作</button><button role="tab" :aria-selected="gestureTab==='settings'" :class="{active:gestureTab==='settings'}" @click="gestureTab='settings'">触发与识别</button></div><div v-show="gestureTab==='editor'" class="gesture-workspace"><section class="gesture-list"><h3>我的手势 <small>{{c.gestures.length}} 条</small></h3><p v-if="!c.gestures.length" class="empty-state">还没有手势。在右侧画出轨迹，选择动作后添加。</p><article class="gesture-rule" v-for="(g,i) in c.gestures" :key="g.id"><div class="gesture-rule-heading"><GestureGlyph :strokes="g.strokes"/><span><strong>{{g.name}}</strong><small><ActionIcon :action="c.actions.find(a=>a.id===g.actionId)" :size="16"/>{{nameFor(g.actionId)}} · {{g.enabled?'已启用':'已停用'}}</small></span></div><div class="gesture-rule-fields"><label><input type="checkbox" v-model="g.enabled" :aria-label="'启用'+g.name">启用此手势</label><label>手势名称<input v-model="g.name" aria-label="手势名称"></label><label>绑定动作<IconSelect label="已有手势绑定动作" v-model="g.actionId" :options="actionOptions" placeholder="选择动作"/></label><button :disabled="!model.validShape(templateStrokes)" @click="rerecord(g)">用当前绘制替换</button><button class="danger" @click="removeGesture(g)">删除</button></div></article></section><div class="gesture-drawing-column"><section class="gesture-canvas"><div class="section-title"><div class="gesture-heading"><h3>绘制与试画</h3><span v-if="drawnValid" class="gesture-match-badge" :class="drawnMatch?'duplicate':'available'" role="status" :title="drawnMatch?'重复手势：'+drawnMatch.name:'当前轨迹可新建手势'">{{drawnMatch?'重复：'+nameFor(drawnMatch.actionId):'可新建'}}</span></div><button @click="resetPad">清空重画</button></div><GesturePad :key="padRevision"  :color="c.gesture.color" @start="onDrawingStart" @record="onRecorded"/></section><section class="gesture-binding"><h3>绑定动作</h3><div class="gesture-binding-fields"><input v-model="newName" placeholder="手势名称"><IconSelect label="手势绑定动作" v-model="newAction" :options="actionOptions" placeholder="选择动作"/><button class="primary" @click="addGesture" :disabled="!newAction||!drawnValid||!!drawnMatch">添加手势</button></div></section></div></div><div v-show="gestureTab==='settings'" class="gesture-settings-scroll"><section class="settings-detail"><div class="settings-card-heading"><h3>触发设置</h3></div><div class="detail-body"><div class="section-title"><label><input type="checkbox" v-model="c.gestureEnabled">启用手势</label></div><div class="form-grid"><label>鼠标按键<select v-model="c.gesture.button"><option v-for="(v,k) in labels" :value="k">{{v}}</option></select></label><label>同时按住<div class="modifiers"><label v-for="m in ['Ctrl','Alt','Shift']"><input type="checkbox" :value="m" v-model="c.gesture.modifiers">{{m}}</label></div></label></div><TriggerRecorder :value="c.gesture" @recorded="v=>{c.gesture.button=v.button;c.gesture.modifiers=v.modifiers;changed()}"/><p class="hint">设置区只编辑草稿，其他应用中继续使用已保存的手势。</p></div></section><section class="settings-detail"><div class="settings-card-heading"><h3>识别与显示</h3></div><div class="detail-body"><div class="form-grid"><label>匹配要求（%，较低更宽容）<input type="number" step="5" min="50" max="95" :value="Math.round(c.gesture.shapeThreshold*100)" @input="c.gesture.shapeThreshold=Number($event.target.value)/100"></label><label>最大绘制时间（毫秒）<input type="number" min="500" max="10000" v-model.number="c.gesture.timeout"></label><label>起手移动距离（px）<input type="number" min="12" max="100" v-model.number="c.gesture.min"></label><label>轨迹颜色<input type="color" v-model="c.gesture.color"></label><label>轨迹粗细<input type="number" min="1" max="12" v-model.number="c.gesture.width"></label></div><label><input type="checkbox" v-model="c.gesture.trail">显示绘制轨迹</label></div></section></div></template>
  <template v-if="page==='actions'"><div class="action-layout"><div class="action-list"><div class="section-title"><h3>全部动作 <small>{{c.actions.length}}</small></h3><button @click="addAction" aria-label="新建动作">＋ 新建动作</button></div><input class="action-search" v-model="actionSearch" placeholder="搜索动作" aria-label="搜索动作"><div class="action-items"><button v-for="{a,i} in filteredActions" :key="a.id" :class="{selected:ai===i}" @click="ai=i"><ActionIcon :action="a" :size="24"/><span><strong>{{a.name}}</strong><small>{{actionTypes[a.type]}}</small></span></button><p v-if="!filteredActions.length" class="empty-state">没有找到动作，换个名称试试。</p></div></div><div class="action-detail"><section v-if="action" class="action-content"><div class="section-title"><h3>动作内容</h3><div class="toolbar"><button @click="copyAction">复制动作</button><button class="danger" @click="removeAction">删除动作</button></div></div><div class="form-grid action-identity"><label>名称<input v-model="action.name"></label><label>图标<ActionIconPicker :key="action.id" :action="action"/></label><label>动作类型<select v-model="action.type" @change="action.value='';changed()"><option value="key">键盘快捷键</option><option value="app">打开应用</option><option value="path">打开文件或文件夹</option><option value="url">打开网址</option><option value="text">输入固定文本</option><option value="plugin">执行 ZTools 插件指令</option></select></label></div><PluginActionFields v-if="action.type==='plugin'" :key="action.id" :action="action" @changed="changed"/><label v-else-if="action.type==='key'">执行快捷键<div class="toolbar"><input v-model="action.value" placeholder="例如 Ctrl+Shift+S"><button :class="{primary:recKey}" @click="keyTarget=null;recKey=!recKey">{{recKey?'请按下快捷键 · Esc 取消':'录入快捷键'}}</button><button @click="action.value='';changed()">清除</button></div></label><template v-else-if="action.type==='app'||action.type==='path'"><label>目标路径<div class="toolbar"><input v-model="action.value"><button @click="choose(action,'file')">选择文件</button><button v-if="action.type==='path'" @click="choose(action,'folder')">选择文件夹</button></div></label><div v-if="action.type==='app'" class="form-grid app-options"><label>启动参数（每行一个）<textarea :value="(action.args||[]).join('\n')" @input="action.args=$event.target.value.split('\n').filter(Boolean)" rows="2"/></label><label>工作目录（可选）<input v-model="action.cwd"></label></div></template><label v-else-if="action.type==='url'">网址<input v-model="action.value" placeholder="https://example.com"></label><label v-else class="action-text">文本内容<textarea v-model="action.value" rows="4" placeholder="输入要插入的固定文本"/></label><div class="action-content-footer"><button class="primary" @click="run(async()=>{await api.save(JSON.parse(JSON.stringify(c)));markSaved();await api.test(action.id)})">保存并在原窗口测试</button><p class="hint">{{c.wheels.reduce((n,w)=>n+[...w.slots,...w.secondSlots,...w.outsideSlots,w.outsideActionId].filter(s=>s===action.id).length,0)}} 个轮盘项、{{c.gestures.filter(g=>g.actionId===action.id).length}} 条手势引用此动作。<br>测试会隐藏设置页，在原窗口执行动作。</p></div></section><section v-else><p>还没有动作，点击“新建动作”开始。</p></section></div></div></template>
  <template v-if="page==='general'"><div class="general-layout"><section><h3>哪些应用不使用鼠快快</h3><p>在这些应用中放行鼠标，不触发轮盘和手势。填写进程名称，每行一个。</p><textarea :value="c.excluded.join('\n')" @input="c.excluded=$event.target.value.split('\n').map(x=>x.trim()).filter(Boolean)" rows="5" placeholder="例如 game.exe"/></section><section><h3>备份与迁移</h3><p>导出包含设置的文本、网址和路径。导入先预览确认，保存后生效。</p><div class="toolbar"><button @click="run(()=>api.export())">导出已保存配置</button><button @click="importConfig">导入配置</button><button class="danger" @click="run(async()=>{if(await askConfirm('恢复所有默认设置？保存后生效。')){c=model.upgrade(api.defaults());wi=ai=0;changed()}})">恢复默认</button></div></section></div></template>
  <footer class="save-bar"><div><strong>{{dirty?'有未保存的修改':'设置已同步'}}</strong><span>{{dirty?'保存后生效，原有配置继续运行':'修改设置后，点击保存应用到桌面'}}</span></div><div class="save-actions"><button v-if="dirty" @click="discard">放弃修改</button><button class="primary" @click="save" :disabled="!dirty">保存设置</button><button v-if="runtime.paused" @click="activate">保存并启用 ↗</button></div></footer></main><Transition name="toast"><div v-if="note" class="toast-message" role="status"><span>{{note}}</span><button @click="note=''" aria-label="关闭提示">×</button></div></Transition>
 <dialog ref="confirmDialog" class="settings-dialog confirm-dialog" @cancel.prevent="answerConfirm(false)"><h3>确认操作</h3><p>{{confirmation}}</p><div class="dialog-actions"><button autofocus @click="answerConfirm(false)">取消</button><button class="danger" @click="answerConfirm(true)">确认</button></div></dialog>
 <dialog ref="actionDialog" class="settings-dialog new-action-dialog" @cancel.prevent="cancelAction"><form v-if="actionDraft" @submit.prevent="saveNewAction"><div class="section-title"><h3>新建动作</h3><button type="button" @click="cancelAction" aria-label="关闭新建动作">×</button></div><p class="hint">填写后保存到动作库，再保存设置即可生效。</p><div class="form-grid"><label>动作名称<input autofocus v-model="actionDraft.name" placeholder="给动作起个名字" required></label><label>执行类型<select v-model="actionDraft.type" @change="actionDraft.value='';cancelKeyRecording()"><option value="key">键盘快捷键</option><option value="app">打开应用</option><option value="path">打开文件或文件夹</option><option value="url">打开网址</option><option value="text">输入固定文本</option><option value="plugin">执行 ZTools 插件指令</option></select></label><label>图标<ActionIconPicker :action="actionDraft"/></label></div><PluginActionFields v-if="actionDraft.type==='plugin'" :action="actionDraft"/><label v-else>执行内容<textarea v-if="actionDraft.type==='text'" v-model="actionDraft.value" rows="4" required/><input v-else v-model="actionDraft.value" :placeholder="actionDraft.type==='key'?'例如 Ctrl+Shift+S':actionDraft.type==='url'?'https://example.com':'文件或应用路径'" required></label><div class="toolbar draft-tools"><button v-if="actionDraft.type==='key'" type="button" @click="keyTarget=actionDraft;recKey=true">{{recKey?'请按下快捷键，Esc 取消':'录入快捷键'}}</button><template v-if="['app','path'].includes(actionDraft.type)"><button type="button" @click="choose(actionDraft,'file')">选择文件</button><button v-if="actionDraft.type==='path'" type="button" @click="choose(actionDraft,'folder')">选择文件夹</button></template></div><template v-if="actionDraft.type==='app'"><label>启动参数（每行一个）<textarea :value="(actionDraft.args||[]).join('\n')" @input="actionDraft.args=$event.target.value.split('\n').filter(Boolean)"/></label><label>工作目录（可选）<input v-model="actionDraft.cwd"></label></template><p v-if="draftError" class="draft-error" role="alert">{{draftError}}</p><div class="dialog-actions"><button type="button" @click="cancelAction">取消</button><button type="submit" class="primary small-save">保存动作</button></div></form></dialog>

 </div><div v-else class="loading">正在载入鼠快快… {{note}}</div>
</template>
